function shoot(shooter,targetX,targetY,enemy=false){let a=Math.atan2(targetY-shooter.y,targetX-shooter.x);shooter.angle=a;let speed=enemy?470:650;bullets.push({x:shooter.x+Math.cos(a)*20,y:shooter.y+Math.sin(a)*20,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:.85,owner:shooter,enemy});if(!enemy)shooter.fire=.19}
function update(dt){if(state!=='playing')return;elapsed+=dt;player.fire=Math.max(0,player.fire-dt);player.inv=Math.max(0,player.inv-dt);let mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),my=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(stickVec.x||stickVec.y){mx=stickVec.x;my=stickVec.y}let mag=Math.hypot(mx,my);if(mag){mx/=mag;my/=mag;player.x+=mx*190*dt;player.y+=my*190*dt}player.x=clamp(player.x,22,1578);player.y=clamp(player.y,22,978);let mWorld={x:cam.x+(mouse.x-W/2),y:cam.y+(mouse.y-H/2)};player.angle=Math.atan2(mWorld.y-player.y,mWorld.x-player.x);if((mouse.down||touchFire)&&player.fire<=0)shoot(player,mWorld.x,mWorld.y);cam.x+=(player.x-cam.x)*Math.min(1,dt*5);cam.y+=(player.y-cam.y)*Math.min(1,dt*5);
let remaining=actors.filter(a=>a.alive);for(let a of remaining){a.fire-=dt;a.wander-=dt;let d=dist(a,player);let target=null;if(d<380)target=player;else{let rival=remaining.filter(b=>b!==a&&dist(a,b)<230).sort((u,v)=>dist(a,u)-dist(a,v))[0];if(rival)target=rival}if(target){a.angle=Math.atan2(target.y-a.y,target.x-a.x);if(d>145){a.x+=Math.cos(a.angle)*a.speed*dt;a.y+=Math.sin(a.angle)*a.speed*dt}if(a.fire<=0&&dist(a,target)<350){shoot(a,target.x+rand(-23,23),target.y+rand(-23,23),true);a.fire=rand(.8,1.5)}}else{if(a.wander<=0){a.angle=rand(-Math.PI,Math.PI);a.wander=rand(1,4)}a.x+=Math.cos(a.angle)*a.speed*.33*dt;a.y+=Math.sin(a.angle)*a.speed*.33*dt}a.x=clamp(a.x,30,1570);a.y=clamp(a.y,30,970);if(elapsed>80){let safe=zone.r;if(dist(a,zone)>safe){a.hp-=dt*4;if(a.hp<=0){a.alive=false}}}}
for(let b of bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.enemy){if(dist(b,player)<player.r+4&&player.inv<=0){health-=11;player.inv=.18;b.life=0;if(health<=0){health=0;finish(false)}}}else{for(let a of actors){if(a.alive&&dist(b,a)<a.r+4){a.hp-=34;b.life=0;if(a.hp<=0){a.alive=false;kills++}break}}}}bullets=bullets.filter(b=>b.life>0);for(let c of crates){if(!c.open&&dist(c,player)<27){c.open=true;health=Math.min(100,health+25);toast()}}if(elapsed>80){zone.r=Math.max(zone.end,zone.start-(elapsed-80)*3.1);if(dist(player,zone)>zone.r){health-=dt*5;if(health<=0){health=0;finish(false)}}}if(actors.every(a=>!a.alive))finish(true);if(Math.floor(elapsed)!==Math.floor(elapsed-dt))ui();ui()}
function toast(){let t=document.getElementById('toast');t.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>t.classList.remove('show'),1250)}
function finish(win){if(state!=='playing')return;state='ended';document.getElementById('endEyebrow').textContent=win?'DELTA DOMINATED':'MATCH COMPLETE';document.getElementById('endTitle').innerHTML=win?'DELTA <span>CHAMPION</span>':'BACK TO <span>THE BANK</span>';document.getElementById('endText').textContent=win?'You outlasted the field and claimed the delta.':'The delta has claimed another runner. Drop back in and try again.';ui();document.getElementById('end').classList.remove('hide')}
function draw(){ctx.clearRect(0,0,W,H);drawWorld();ctx.save();ctx.translate(W/2-cam.x,H/2-cam.y);for(let c of crates){if(c.open)continue;ctx.fillStyle='#18281b';ctx.fillRect(c.x-10,c.y-10,20,20);ctx.fillStyle='#d8f36a';ctx.fillRect(c.x-8,c.y-8,16,16);ctx.fillStyle='#657c3b';ctx.fillRect(c.x-2,c.y-8,4,16);ctx.fillRect(c.x-8,c.y-2,16,4)}ctx.restore();for(let a of actors)drawActor(a);if(player)drawActor(player,true);for(let b of bullets){let p=screenPos(b);ctx.fillStyle=b.enemy?'#ff8b68':'#efff9a';ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fill()}drawZone();if(state==='playing'){requestAnimationFrame(frame)}}
function drawZone(){let p=screenPos(zone);ctx.save();ctx.fillStyle='#b9e8ea18';ctx.beginPath();ctx.rect(0,0,W,H);ctx.arc(p.x,p.y,zone.r,0,Math.PI*2,true);ctx.fill('evenodd');ctx.strokeStyle='#d9f36a';ctx.globalAlpha=.72;ctx.lineWidth=2;ctx.setLineDash([9,8]);ctx.beginPath();ctx.arc(p.x,p.y,zone.r,0,Math.PI*2);ctx.stroke();ctx.restore()}
function frame(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt);draw()}

